WITH paid_orders AS (SELECT o.customer_id,o.order_id,o.ordered_at,SUM(i.quantity*i.unit_price_cents) AS cents FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.customer_id,o.order_id,o.ordered_at), lifetime AS (SELECT customer_id,MAX(ordered_at) AS last_paid_at,SUM(cents) AS paid_cents FROM paid_orders GROUP BY customer_id) SELECT c.customer_id,c.full_name,l.last_paid_at,COALESCE(l.paid_cents,0) AS paid_cents FROM customers c LEFT JOIN lifetime l ON l.customer_id=c.customer_id ORDER BY c.customer_id;
